    for r in range(H):
        for c in range(W):
            if not seen[r][c] and g[r][c]:
                stack=[(r,c)]; cells=[]; seen[r][c]=1
                while stack:
                    a,b=stack.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and not seen[na][nb] and g[na][nb]:
                            seen[na][nb]=1; stack.append((na,nb))
                s=set(g[a][b] for a,b in cells)
                if best is None or len(s)>best[0]:
                    best=(len(s), min(a for a,b in cells), max(a for a,b in cells), min(b for a,b in cells), max(b for a,b in cells), s, cells)
    r0,r1,c0,c1=best[1],best[2],best[3],best[4]
    return [g[i][c0:c1+1] for i in range(r0,r1+1)]
